    <div className="sa-empty">
      {icon && <div className="sa-empty__icon">{icon}</div>}
      <div className="sa-empty__body">
        <span className="sa-empty__title">{title}</span>
        {description && <span className="sa-empty__desc">{description}</span>}
      </div>
      {action}
    </div>
  );
}

