},

          outlineOffset: "2px",
          borderRadius: "var(--radius-pill)",
        }}
      >
        <span className={`badge badge-${getStatusPresentation("quote", s).badgeVariant}`}>{t(`quotes.status_${s}`)}</span>
      </button>
    );
  })}
</div>

},
{
  key: "shift_type",
  header: t("shifts.shiftType"),
  renderCell: (s) => <span className="badge badge-negotiating">{s.shift_type}</span>,
},
{
  key: "actions",
  header: t("common.actions"),

{
  key: "status",
  header: t("staff.status"),
  renderCell: (s) => (
    <span className={`badge badge-${getStatusPresentation("staff", s.status).badgeVariant}`}>
      {t(getStatusPresentation("staff", s.status).labelKey ?? `staff.status_${s.status}`)}
    </span>
  ),
},

